// 鐣竴寮电洡闈?g = 鍦栨銆乵 = 鍊嶆暩;鏍煎瓙 index = 娆?* 5 + 鍒?鐣潰涓婁竴鍒椾竴鍒楁帓銆俓n// drop:true = 鏁寸洡涓€娆勪竴娆勬帀涓嬩締;'changed' = 鍙湁璁婁簡鐨勬牸瀛愬緸涓婇潰鎺変笅渚?娑堥櫎寰岃涓?
function evaDrawFrame(g, m, { drop }) {
  const cells = evaCells();
  const fast = EVA.fast;
  for (let c = 0; c < EVA_COLS; c++) {
    let fresh = 0; // 閫欎竴娆勬湁骞炬牸鏄柊鐨?鎺夌殑璺濋洟)
