  evaFxStart();
}
// 鍏嶈不閬婃埐:鎻?BOSS(鍦栨槸绗竴娆＄敤鎵嶄笅杓?;acc = 绱鍊嶆暩,澶氫竴榛炲氨鎬掓埃姊濇疾涓€榛?鍐嶈Ц鐧兼檪鐙傛毚
function evaStageBoss(on) {
  if (!ST.on) return;
  ST.boss = on;
  ST.rage = 0;
  if (on) evaStageMonster(EVA_BOSS_GFX);
}
function evaStageRage(acc, grew) {
  if (!ST.on || !ST.boss) return;
