    if (isEquipped(it)) continue;
    if (m.unsealedOnly && (it.bless == null || it.bless >= 128 || st.locks?.has(it.id))) continue;
    if (st.craftFeatures?.includes('SealedCraftEnabled') && st.locks?.has(it.id)) continue;
    if (m.enchant != null) {
