  if (wis <= 14) return 0;
  if (wis <= 16) return 3;
  const table = { 17: 6, 18: 10, 19: 15, 20: 21, 21: 28, 22: 37, 23: 47 };
  if (table[wis] != null) return table[wis];
  if (wis >= 50) return 65;
